import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.C-si7TFR.js";const m=JSON.parse('{"title":"Your first task","description":"Start IOLinker safely, connect a model, complete a conversation and build a visual workflow.","frontmatter":{"title":"Your first task","description":"Start IOLinker safely, connect a model, complete a conversation and build a visual workflow."},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md"}'),i={name:"guide/quick-start.md"};function n(s,e,l,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="your-first-task" tabindex="-1">Your first task <a class="header-anchor" href="#your-first-task" aria-label="Permalink to &quot;Your first task&quot;">​</a></h1><p>This path does not depend on legacy robot triggers. Complete one small, inspectable task before adding schedules, remote access or business integrations.</p><h2 id="_1-start-and-secure-the-installation" tabindex="-1">1. Start and secure the installation <a class="header-anchor" href="#_1-start-and-secure-the-installation" aria-label="Permalink to &quot;1. Start and secure the installation&quot;">​</a></h2><ol><li>Download the package matching your operating system and CPU architecture from the <a href="https://iolinker.com/#cta" target="_blank" rel="noreferrer">official download section</a>. Do not infer architecture from the term “NAS”.</li><li>Open the local web address reported by the program. Use its startup log for the actual port.</li><li>Complete the first login and immediately change the initial password from the account menu. This guide provides no fixed default credentials.</li><li>Do not expose the service publicly or share cookies, tokens or configuration files before completing account security.</li></ol><p>See <a href="./deployment.html">Installation and deployment</a> for boundaries.</p><h2 id="_2-connect-a-model" tabindex="-1">2. Connect a model <a class="header-anchor" href="#_2-connect-a-model" aria-label="Permalink to &quot;2. Connect a model&quot;">​</a></h2><ol><li>Open a conversation in the agent workspace. If no usable model exists, the page displays model setup guidance.</li><li>Use <strong>Quick setup</strong> or <strong>Model settings</strong> to select a provider and enter its required model name, endpoint and API key.</li><li>Save, return to the conversation and confirm that the model is available before selecting or creating an agent.</li><li>Keep only necessary tools. Do not authorize files, commands or remote channels for this first task.</li></ol><p>Model providers are usually third parties. Prompts, conversations, retrieved snippets and tool data may be sent to them. Saving a configuration does not prove connectivity or available credit.</p><h2 id="_3-complete-a-conversation" tabindex="-1">3. Complete a conversation <a class="header-anchor" href="#_3-complete-a-conversation" aria-label="Permalink to &quot;3. Complete a conversation&quot;">​</a></h2><ol><li>Open the new agent&#39;s conversation.</li><li>Give it a small, explicit task: <code>Summarize the capabilities you can call and tell me which actions require additional authorization.</code></li><li>Wait for the streamed response and inspect tool cards, errors and task results.</li><li>Find the saved session in the conversation list and use the trace entry to distinguish the agent session from scheduled tasks.</li></ol><p><strong>Success means:</strong> a readable response appears without model authentication or tool permission errors. A sent request alone is not a completed task.</p><h2 id="_4-build-a-workflow" tabindex="-1">4. Build a workflow <a class="header-anchor" href="#_4-build-a-workflow" aria-label="Permalink to &quot;4. Build a workflow&quot;">​</a></h2><ol><li>Switch to workflow mode and use <strong>New</strong> to create an empty flow.</li><li>Keep the <strong>manual trigger</strong> and add an <a href="./../llm.html">LLM node</a>. Select the model credential and configure its input as required by the interface.</li><li>Connect the result to <a href="./../output.html">Output</a>, save the flow and execute it manually.</li><li>Open execution records and inspect node states, inputs, outputs and errors.</li></ol><p><strong>Success means:</strong> the flow has a clear completion state and the output matches the task. Fix model and node configuration before enabling unattended execution.</p><h2 id="_5-extend-gradually" tabindex="-1">5. Extend gradually <a class="header-anchor" href="#_5-extend-gradually" aria-label="Permalink to &quot;5. Extend gradually&quot;">​</a></h2><ul><li>For agent-assisted creation and debugging, read <a href="./workflows.html">Workflows and troubleshooting</a>.</li><li>For recurring execution, distinguish <a href="./schedules.html">agent schedules</a> from workflow Crontab.</li><li>For private reference material, check <a href="./knowledge.html">knowledge and retrieval</a> prerequisites.</li><li>For human input and approval, read <a href="./forms.html">Forms and collaboration</a>.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>No model available:</strong> check model settings, project context and provider configuration. Models are not assumed to be preconfigured.</li><li><strong>The task is waiting:</strong> inspect tool authorization, model responses and task status rather than treating elapsed time as success.</li><li><strong>A legacy robot menu is missing:</strong> new entries for those triggers are hidden from the current node menu.</li><li><strong>The package differs from this guide:</strong> guides reflect current source; use the installed package&#39;s interface. Not every released package contains these capabilities.</li></ul>',18)])])}const p=t(i,[["render",n]]);export{m as __pageData,p as default};
